sql.if:
AND EXISTS ( SELECT rdf_prpty_id
               FROM dtmeta.tb_rdf_propertydefine def 
              WHERE def.rdf_class_id = #{rdfClassId}
                AND def.rdf_prpty_id = t1.rdf_prpty_id
           )

AND EXISTS ( SELECT rdf_prpty_id
FROM dtmeta.tb_rdf_propertydefine def
WHERE def.rdf_class_id = #{rangeRdfClassId}
    AND def.rdf_prpty_id = t1.rdf_prpty_id
    AND def.domn_range_div_mtcd = 'range'
)

mapper.select:
/* SQL_ID: RdfPropertyMapper.selectDomainRdfPropertyCount */ WITH RECURSIVE class_tree AS ( SELECT rdf_class_id, up_rdf_class_id FROM dtmeta.tb_rdf_class WHERE rdf_class_id = #{rdfClassId} UNION ALL SELECT t1.rdf_class_id, t1.up_rdf_class_id FROM dtmeta.tb_rdf_class t1 JOIN class_tree ct ON t1.rdf_class_id = ct.up_rdf_class_id ) SELECT COUNT(DISTINCT t1.rdf_prpty_id) FROM dtmeta.tb_rdf_property t1 LEFT JOIN dtmeta.tb_rdf_propertydefine t2 ON t2.rdf_prpty_id = t1.rdf_prpty_id LEFT JOIN class_tree ct ON t2.rdf_class_id = ct.rdf_class_id LEFT JOIN dtmeta.tb_rdf_namespace t3 ON t1.rdf_nmsp_id = t3.rdf_nmsp_id LEFT JOIN ( SELECT id_all_mtcd.rdf_prpty_id, string_agg(mtcd_nm, ',') AS mtcd_nm FROM ( SELECT rdf_prpty_id, unnest( string_to_array(rdf_form_mtcds, ',') ) AS each_mtcd FROM dtmeta.tb_rdf_property ORDER BY 1, 2 ) id_all_mtcd LEFT JOIN dtmeta.tb_portal_code ptcd ON id_all_mtcd.each_mtcd = ptcd.mtcd AND ptcd.mtcd_grp_id = 'MCG00009' GROUP BY id_all_mtcd.rdf_prpty_id ) t5 ON t1.rdf_prpty_id = t5.rdf_prpty_id WHERE t2.domn_range_div_mtcd = 'domain' AND t2.rdf_class_id IN ( SELECT rdf_class_id FROM class_tree )
AND ( t1.rdf_form_mtcds = #{rdfFormMtcd} OR t1.rdf_form_mtcds LIKE CONCAT('%,', #{rdfFormMtcd}) OR t1.rdf_form_mtcds LIKE CONCAT(#{rdfFormMtcd}, ',%') OR t1.rdf_form_mtcds LIKE CONCAT('%,', #{rdfFormMtcd}, ',%') )
AND t3.rdf_nmsp_id = #{rdfNmspId}
AND( t1.rdf_prpty_nm ILIKE CONCAT('%', #{searchPrptyNm}, '%') OR t1.rdf_prpty_logic_nm ILIKE CONCAT('%', #{searchPrptyNm}, '%') )

/* SQL_ID: RdfPropertyMapper.selectDomainRdfPropertyList */ WITH RECURSIVE class_tree AS ( SELECT rdf_class_id, up_rdf_class_id FROM dtmeta.tb_rdf_class WHERE rdf_class_id = #{rdfClassId} UNION ALL SELECT t1.rdf_class_id, t1.up_rdf_class_id FROM dtmeta.tb_rdf_class t1 JOIN class_tree ct ON t1.rdf_class_id = ct.up_rdf_class_id ) SELECT t1.rdf_prpty_id, ( ROW_NUMBER() OVER( ORDER BY t1.rdf_prpty_nm ASC ) ) AS rownum, t1.rdf_form_mtcds, t5.mtcd_nm AS rdf_form_mtcd_nm_str, t1.rdf_nmsp_id, t1.rdf_prpty_nm, t1.rdf_prpty_desc, t1.rdf_prpty_logic_nm, t1.up_rdf_prpty_id, t1.rdf_prpty_regr_id, t1.rdf_prpty_regr_nm, to_char(t1.rdf_prpty_reg_dt, #{sqlDateFormat}) AS rdf_prpty_reg_dt, t1.rdf_prpty_amdr_id, t1.rdf_prpty_amdr_nm, to_char(t1.rdf_prpty_amd_dt, #{sqlDateFormat}) AS rdf_prpty_amd_dt, CONCAT( t3.rdf_nmsp_pfix, ':', t1.rdf_prpty_nm ) rdf_prpty, string_agg(tb_sub.rdf_class, ',' ORDER BY tb_sub.rdf_class) rdf_class_str FROM dtmeta.tb_rdf_property t1 LEFT JOIN dtmeta.tb_rdf_propertydefine t2 ON t2.rdf_prpty_id = t1.rdf_prpty_id LEFT JOIN class_tree ct ON t2.rdf_class_id = ct.rdf_class_id LEFT JOIN dtmeta.tb_rdf_namespace t3 ON t1.rdf_nmsp_id = t3.rdf_nmsp_id LEFT JOIN ( SELECT id_all_mtcd.rdf_prpty_id, string_agg(mtcd_nm, ',') AS mtcd_nm FROM ( SELECT rdf_prpty_id, unnest(string_to_array(rdf_form_mtcds, ',')) AS each_mtcd FROM dtmeta.tb_rdf_property ORDER BY 1, 2 ) id_all_mtcd LEFT JOIN dtmeta.tb_portal_code ptcd ON id_all_mtcd.each_mtcd = ptcd.mtcd AND ptcd.mtcd_grp_id = 'MCG00009' GROUP BY id_all_mtcd.rdf_prpty_id ) t5 ON t1.rdf_prpty_id = t5.rdf_prpty_id LEFT JOIN ( SELECT t3.rdf_prpty_def_id, t2.rdf_prpty_id, t3.rdf_class_id, CASE WHEN t3.rdf_prpty_id IS NOT NULL THEN CONCAT(n1.rdf_nmsp_pfix, ':', t4.rdf_class_nm) ELSE NULL END AS rdf_class FROM dtmeta.tb_rdf_property t2 LEFT JOIN dtmeta.tb_rdf_propertydefine t3 ON t3.rdf_prpty_id = t2.rdf_prpty_id LEFT JOIN dtmeta.tb_rdf_class t4 ON t4.rdf_class_id = t3.rdf_class_id LEFT JOIN dtmeta.tb_rdf_namespace n1 ON n1.rdf_nmsp_id = t4.rdf_nmsp_id ORDER BY rdf_prpty_def_odrg ) tb_sub ON tb_sub.rdf_prpty_id = t1.rdf_prpty_id WHERE 1 = 1 AND t2.domn_range_div_mtcd = 'domain' AND t2.rdf_class_id IN ( SELECT rdf_class_id FROM class_tree )
AND ( t1.rdf_form_mtcds = #{rdfFormMtcd} OR t1.rdf_form_mtcds ~ ('(^|,)' || #{rdfFormMtcd} || '($|,)') )
AND t3.rdf_nmsp_id = #{rdfNmspId}
AND( t1.rdf_prpty_nm ILIKE CONCAT('%', #{searchPrptyNm}, '%') OR t1.rdf_prpty_logic_nm ILIKE CONCAT('%', #{searchPrptyNm}, '%') )
GROUP BY t1.rdf_prpty_id, t1.rdf_form_mtcds, t5.mtcd_nm, t1.rdf_nmsp_id, t1.rdf_prpty_nm, t1.rdf_prpty_desc, t1.rdf_prpty_logic_nm, t1.up_rdf_prpty_id, t1.rdf_prpty_regr_id, t1.rdf_prpty_regr_nm, t1.rdf_prpty_reg_dt, t1.rdf_prpty_amdr_id, t1.rdf_prpty_amdr_nm, t1.rdf_prpty_amd_dt, t3.rdf_nmsp_pfix ORDER BY t1.rdf_prpty_nm ASC

mapper.update:
UPDATE  /* SQL_ID: RdfPropertyMapper.updateRdfProperty */
    dtmeta.tb_rdf_property
SET
    rdf_form_mtcds = #{rdfFormMtcds}
    , rdf_nmsp_id = #{rdfNmspId}
    , rdf_prpty_nm = #{rdfPrptyNm}
    , rdf_prpty_desc = #{rdfPrptyDesc}
    , up_rdf_prpty_id = #{upRdfPrptyId}
    , rdf_prpty_logic_nm = #{rdfPrptyLogicNm}
    , rdf_prpty_amd_dt = current_timestamp
    , rdf_prpty_amdr_id =   #{rdfPrptyAmdrId}
    , rdf_prpty_amdr_nm = #{rdfPrptyAmdrNm}
WHERE rdf_prpty_id = #{rdfPrptyId}

mapper.delete:
DELETE  /* SQL_ID: RdfPropertyMapper.deleteRdfProperty */
FROM dtmeta.tb_rdf_property
WHERE rdf_prpty_id = #{rdfPrptyId}

mapper.select:
SELECT EXISTS (  /* SQL_ID: RdfPropertyMapper.validationDuringDeleteMode */
    SELECT 1
    FROM dtmeta.tb_rdf_propertydefine
    WHERE rdf_prpty_id = #{rdfPrptyId} AND domn_range_div_mtcd = 'domain'
)
OR EXISTS (
    SELECT 1
    FROM dtmeta.tb_rdf_mappingrule
    WHERE rdf_prpty_id = #{rdfPrptyId}
)

SELECT EXISTS (   /* SQL_ID: RdfPropertyMapper.validationDuringEditMode */
    SELECT 1
    FROM dtmeta.tb_rdf_property
    WHERE
    rdf_prpty_id != #{rdfPrptyId} AND rdf_nmsp_id = #{rdfNmspId} AND rdf_prpty_nm = #{rdfPrptyNm}
)

SELECT EXISTS (  /* SQL_ID: RdfPropertyMapper.validationDefineDuringEditMode */
    SELECT 1
    FROM dtmeta.tb_rdf_propertydefine
    WHERE domn_range_div_mtcd = #{domnRangeDivMtcd} AND rdf_class_id = #{rdfClassId} AND rdf_prpty_id = #{rdfPrptyId}
)

SELECT t2.*  /* SQL_ID: RdfPropertyMapper.selectRdfPropertyDefine */
FROM  dtmeta.tb_rdf_propertydefine t2
WHERE t2.rdf_prpty_def_id = #{rdfPrptyDefId}

mapper.delete:
DELETE  /* SQL_ID: RdfPropertyMapper.deleteRdfPropertyDefine */
FROM dtmeta.tb_rdf_propertydefine
WHERE rdf_prpty_def_id = #{rdfPrptyDefId}

DELETE  /* SQL_ID: RdfPropertyMapper.deleteRdfPropertyDefineByProperty */
FROM dtmeta.tb_rdf_propertydefine
WHERE rdf_prpty_id = #{rdfPrptyId}
